<?php $naslovStranice='Iznajmljivanja';require __DIR__.'/../delovi/zaglavlje.php';?><main class="stranica"><div class="breadcrumb"><a href="index.php?stranica=pocetna">Početna</a><span>›</span><strong>Iznajmljivanja</strong></div><section class="panel"><div class="sekcija-zaglavlje"><div><h1>Evidencija iznajmljivanja</h1><p>Master-detail dokumenti sa naprednom pretragom.</p></div><a class="dugme" href="index.php?stranica=iznajmljivanje-dodaj">+ Novo iznajmljivanje</a></div><?php if($poruka):?><div class="<?=($poruka['tip']??'')==='greska'?'greska':'poruka'?>"><?=htmlspecialchars($poruka['tekst'])?></div><?php endif;?><form class="napredni-filter" method="get"><input type="hidden" name="stranica" value="iznajmljivanja"><input name="filter" value="<?=htmlspecialchars($filter)?>" placeholder="Klijent, mejl, ID..."><select name="status"><option value="">Svi statusi</option><option value="Aktivno" <?=$f['status']==='Aktivno'?'selected':''?>>Aktivno</option><option value="Zavrseno" <?=$f['status']==='Zavrseno'?'selected':''?>>Završeno</option></select><select name="klijentId"><option value="">Svi klijenti</option><?php foreach($klijenti as $k):?><option value="<?=$k['ID']?>" <?=(string)$f['klijentId']===(string)$k['ID']?'selected':''?>><?=htmlspecialchars($k['Ime'].' '.$k['Prezime'])?></option><?php endforeach;?></select><select name="voziloId"><option value="">Sva vozila</option><?php foreach($vozilaFilter as $v):?><option value="<?=$v['ID']?>" <?=(string)$f['voziloId']===(string)$v['ID']?'selected':''?>><?=htmlspecialchars($v['Marka'].' '.$v['Model'].' '.$v['Registracija'])?></option><?php endforeach;?></select><input type="date" name="datumOd" value="<?=htmlspecialchars($f['datumOd'])?>"><input type="date" name="datumDo" value="<?=htmlspecialchars($f['datumDo'])?>"><input type="number" min="0" name="minCena" value="<?=htmlspecialchars($f['minCena'])?>" placeholder="Min cena"><input type="number" min="0" name="maxCena" value="<?=htmlspecialchars($f['maxCena'])?>" placeholder="Max cena"><button>Filtriraj</button><a class="dugme dugme-sekundarno" href="index.php?stranica=iznajmljivanja">Očisti</a></form><div class="sekcija-zaglavlje"><span class="broj-rezultata"><?=$ukupno?> rezultata</span><a class="dugme dugme-sekundarno" target="_blank" href="index.php?stranica=stampa-spisak&filter=<?=urlencode($filter)?>">Štampa</a></div><div class="tabela-okvir"><table><thead><tr><th>ID</th><th>Klijent</th><th>Period</th><th>Status</th><th>Vraćeno</th><th>Ukupno</th><th>Akcije</th></tr></thead><tbody><?php foreach($redovi as $r):?><tr><td><strong>#<?=$r['ID']?></strong></td><td><?=htmlspecialchars($r['Ime'].' '.$r['Prezime'])?></td><td><?=$r['DatumOd']?> — <?=$r['DatumDo']?></td><td><span class="status <?=$r['Status']==='Aktivno'?'status-aktivan':'status-zavrsen'?>"><?=htmlspecialchars($r['Status'])?></span></td><td><?=!empty($r['DatumVracanja'])?htmlspecialchars($r['DatumVracanja']):'—'?><?php if((int)($r['KasnjenjeDana']??0)>0):?><br><small>Kasnilo <?=((int)($r['KasnjenjeDana']??0))?> dana</small><?php endif;?></td><td><strong><?=number_format((float)$r['UkupnaCena'],2,',','.')?> RSD</strong></td><td><div class="akcije"><a href="index.php?stranica=iznajmljivanje-detalji&id=<?=$r['ID']?>">Detalji</a><?php if($r['Status']==='Aktivno'):?><a href="index.php?stranica=iznajmljivanje-izmeni&id=<?=$r['ID']?>">Izmeni</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if($brojStr>1):?><nav class="paginacija"><?php for($i=1;$i<=$brojStr;$i++):?><a class="<?=$i===$str?'aktivna':''?>" href="?<?=htmlspecialchars(http_build_query(array_merge($_GET,['str'=>$i])))?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></section></main><?php require __DIR__.'/../delovi/podnozje.php';?>